L1_user_onboarding.invariants_dsl:
spec UserOnboarding {
    field username: String {}
    field age: Integer {
        value >= 18;
        value <= 120;
    }
    field country_code: String {
        value IN ["US", "GB", "DE", "FR", "JP"];
    }
    field is_verified: Boolean {
        value == true;
    }
    field terms_accepted: Boolean {
        value == true;
    }
}

L1_iot_telemetry.invariants_dsl:
spec SensorTelemetry {
    field device_id: String {}
    field temperature_c: Number {
        value >= -40.0;
        value <= 85.0;
    }
    field humidity_pct: Number {
        value >= 0.0;
        value <= 100.0;
    }
    field battery_level: Integer {
        value >= 0;
        value <= 100;
    }
    field status: String {
        value IN ["OK", "WARNING", "CRITICAL"];
    }
}

L1_network_security_rule.invariants_dsl:
spec SecurityRule {
    field rule_name: String {}
    field protocol: String {
        value IN ["TCP", "UDP", "ICMP"];
    }
    field port: Integer {
        value >= 1;
        value <= 65535;
    }
    field direction: String {
        value IN ["INGRESS", "EGRESS"];
    }
    field priority: Integer {
        value >= 10;
        value <= 1000;
    }
    field is_enabled: Boolean {
        value == true;
    }
}
